insert into stages (position,name,purpose,insight,prospect_says,happened_options) values
(1,'Opening','Reach the right person and say who you are. They decide in ten seconds if this is worth a minute.','About 13 of 100 calls die here: wrong person or person gone.',
 $$[{"line":"Who is this? Calling from where? (asks twice)","seen_in":30},{"line":"Switchboard: what is it regarding?","seen_in":19},{"line":"He left a long time ago / this number is not theirs","seen_in":13},{"line":"Driving, in a meeting, travelling","seen_in":9}]$$,
 $$[{"key":"right_person","label":"Right person"},{"key":"reception","label":"Reception answered"},{"key":"wrong_person","label":"Wrong person"},{"key":"moved_company","label":"Left the company"}]$$),
(2,'Purpose','Say in one or two sentences why you called, in words they can repeat to a colleague.','Most common reaction is what is this regarding?',
 $$[{"line":"What is this regarding? What does that mean, actually?","seen_in":23},{"line":"Where did you get my number?","seen_in":3},{"line":"Why are you asking about my company?","seen_in":4},{"line":"We are not into this kind of thing","seen_in":5}]$$,
 $$[{"key":"asked_what","label":"Asked what we do"},{"key":"asked_source","label":"Asked where we got the number"},{"key":"sales_call","label":"Said it is a sales call"},{"key":"let_go_on","label":"Let me go on"}]$$),
(3,'Permission','Find out if they will talk now. A clear yes, no, or named callback time is useful.','Permission was asked before purpose in 55 of 100 calls.',
 $$[{"line":"Call me in an hour / after my meeting","seen_in":22},{"line":"Send it on WhatsApp first","seen_in":25},{"line":"Short yes, then waits","seen_in":null},{"line":"Keeps talking without answering (not a yes)","seen_in":null}]$$,
 $$[{"key":"yes_now","label":"Yes, go ahead"},{"key":"callback_time","label":"Gave a callback time"},{"key":"send_first","label":"Asked me to send first"},{"key":"no_clear_yes","label":"No clear yes"}]$$),
(4,'Their business','Ask about their company and work before saying more about yours.','Callers often move to sending a report before exploring the business.',
 $$[{"line":"One-line answer, then waits for the pitch","seen_in":null},{"line":"We are a small company / back office","seen_in":null},{"line":"That is not my area","seen_in":null},{"line":"You tell me about yourself first","seen_in":null}]$$,
 $$[{"key":"described_business","label":"Described their business"},{"key":"one_liner","label":"One-line answer"},{"key":"corrected_us","label":"Corrected us"},{"key":"asked_about_us","label":"Asked about us first"}]$$),
(5,'Their need, in their words','Hear what they are trying to do or struggling with. Write down exactly what they said.','Capture their exact words.',
 $$[{"line":"Grow revenue, improve profitability, enter a new market","seen_in":null},{"line":"Everything is fine, nothing needed","seen_in":null},{"line":"Is this a vendor project? Do we have to pay?","seen_in":null},{"line":"Why would we share that data?","seen_in":null}]$$,
 $$[{"key":"named_goal","label":"Named a goal"},{"key":"nothing_needed","label":"Said nothing needed"},{"key":"asked_cost","label":"Asked about cost"},{"key":"asked_what_we_can_do","label":"Asked what we can do"}]$$),
(6,'Objection','Understand the reason for the no before answering.','The no is often wrong person or an existing provider.',
 $$[{"line":"We already have consultants / the parent company handles it","seen_in":10},{"line":"Not the right person: CFO / GM / another team","seen_in":13},{"line":"Not interested right now","seen_in":7},{"line":"Send something in writing","seen_in":null}]$$,
 $$[{"key":"has_provider","label":"Has consultant / in-house"},{"key":"wrong_person","label":"Wrong person, named who"},{"key":"not_interested","label":"Not interested"},{"key":"in_writing","label":"Wants it in writing"}]$$),
(7,'Next step','Agree one concrete thing with a time or a channel.','WhatsApp is common; verify the correct number.',
 $$[{"line":"Send it on WhatsApp / email","seen_in":39},{"line":"A day and time they name","seen_in":null},{"line":"A different WhatsApp number or email","seen_in":null},{"line":"A colleague to talk to","seen_in":4}]$$,
 $$[{"key":"whatsapp","label":"Send on WhatsApp"},{"key":"email","label":"Send by email"},{"key":"call_time","label":"Call at a time they named"},{"key":"referral","label":"Referral to colleague"}]$$),
(8,'Close','End clearly and record outcome, next step and the prospect words from stage 5.','Some calls marked not logged have an agreed next step.',
 $$[{"line":"Line dropped or they hung up mid-sentence","seen_in":null},{"line":"Warm goodbye after a no","seen_in":null},{"line":"Logged outcome does not match what was said","seen_in":null}]$$,
 $$[{"key":"clean_end","label":"Clean ending"},{"key":"dropped","label":"Line dropped"},{"key":"hung_up","label":"They hung up"},{"key":"warm_no","label":"Warm goodbye, a no"}]$$)
on conflict (position) do nothing;
